import React from "react";

function MembersModal({
  list,
  allUsers,
  currentUser,
  onClose,
  onRemoveMember,
}) {
  const isOwner = list.owner === currentUser;

  return (
  
    <div className="modal-overlay" onClick={onClose}>
{}
      <div className="modal-content" onClick={(e) => e.stopPropagation()}>
        <div className="modal-header">
          <h2>Members</h2>
          <button className="close-button" onClick={onClose}>
            &times;
          </button>
        </div>
        <div className="modal-body">
          {list.members.map((memberId) => {
            const member = allUsers[memberId] || { name: "Unknown user" };
            const isSelf = memberId === currentUser;
            const isThisMemberTheOwner = memberId === list.owner;

           
            const showRemoveButton = (isOwner && !isSelf) || (!isOwner && isSelf);

            return (
              <div key={memberId} className="member-item">
                <span className="member-name">
                  {member.name}
                  {isThisMemberTheOwner && (
                    <span className="owner-tag">owner</span>
                  )}
                </span>
                {showRemoveButton && (
                  <button
                    className="button-danger"
                    onClick={() => onRemoveMember(memberId)}
                  >
                    {isSelf ? "Leave" : "Remove"}
                  </button>
                )}
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
}

export default MembersModal;
